<?php
// Isolated CLI-only feedback regression. Never reads site config.
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
$dsn=getenv('CHAOXI_TEST_DSN'); $user=getenv('CHAOXI_TEST_USER'); $pass=getenv('CHAOXI_TEST_PASSWORD');
if (!$dsn || strpos($dsn,'mysql:')!==0 || preg_match_all('/(?:^|;)\s*dbname\s*=/i',substr($dsn,6))!==1 || !preg_match('/(?:^|;)dbname=chaoxi_wallet_test_[A-Za-z0-9_]+(?:;|$)/',substr($dsn,6))) throw new RuntimeException('仅允许显式 chaoxi_wallet_test_ DSN');
$pdo=new PDO($dsn,$user,$pass,array(PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false));
if(!preg_match('/^chaoxi_wallet_test_[A-Za-z0-9_]+$/',(string)$pdo->query('SELECT DATABASE()')->fetchColumn())) throw new RuntimeException('实际数据库名称不符合隔离前缀');
$root=dirname(__DIR__); require $root.'/scripts/migrate.php'; spl_autoload_register(function($c)use($root){foreach(array('/app/Services/','/app/Core/') as $d){$f=$root.$d.$c.'.php';if(is_file($f))require_once$f;}});
function ok($x,$m){if(!$x)throw new RuntimeException('FAIL '.$m);echo "PASS $m\n";}
function reject($f,$m,$expected){try{$f();}catch(PDOException $e){throw $e;}catch(Exception $e){if(!($e instanceof InvalidArgumentException)&&!($e instanceof RuntimeException))throw $e;if(strpos($e->getMessage(),$expected)===false)throw new RuntimeException('FAIL unexpected rejection '.$m.': '.$e->getMessage());echo "PASS $m\n";return;}throw new RuntimeException('FAIL '.$m);}
if(isset($argv[1])&&$argv[1]==='--worker'){try{(new FeedbackService($pdo))->review((int)$argv[2],(int)$argv[3],'rewarded',$argv[4],$argv[5]);echo 'OK';exit(0);}catch(PDOException $e){fwrite(STDERR,$e->getMessage());exit(3);}catch(RuntimeException $e){if($e->getMessage()!=='操作后余额超过钱包上限。'){fwrite(STDERR,$e->getMessage());exit(3);}echo 'REJECT: '.$e->getMessage();exit(2);}}
function parallel_reviews($jobs){$children=array();foreach($jobs as $job){$pipes=array();$p=proc_open(array_merge(array(PHP_BINARY,__FILE__,'--worker'),$job),array(0=>array('pipe','r'),1=>array('pipe','w'),2=>array('pipe','w')),$pipes);if(!is_resource($p))throw new RuntimeException('并发进程创建失败');fclose($pipes[0]);$children[]=array($p,$pipes);} $success=0;foreach($children as $c){$out=stream_get_contents($c[1][1]);$err=stream_get_contents($c[1][2]);fclose($c[1][1]);fclose($c[1][2]);$code=proc_close($c[0]);if($code===0&&$out==='OK')$success++;elseif($code!==2||$out!=='REJECT: 操作后余额超过钱包上限。'||$err!=='')throw new RuntimeException('并发失败：'.$out.$err);}return $success;}
run_migrations($pdo,$root); run_migrations($pdo,$root); ok(true,'repeated migration');
$stamp=bin2hex(random_bytes(6));$now=date('Y-m-d H:i:s');
$pdo->prepare('INSERT INTO users(email,password_hash,display_name,created_at,updated_at) VALUES(? ,"x","feedback",?,?)')->execute(array($stamp.'@test.local',$now,$now));$uid=(int)$pdo->lastInsertId();
$pdo->prepare('INSERT INTO users(email,password_hash,display_name,created_at,updated_at) VALUES(? ,"x","other",?,?)')->execute(array('o'.$stamp.'@test.local',$now,$now));$other=(int)$pdo->lastInsertId();
$pdo->prepare('INSERT INTO admin_users(email,password_hash,created_at,updated_at) VALUES(? ,"x",?,?)')->execute(array('a'.$stamp.'@test.local',$now,$now));$a1=(int)$pdo->lastInsertId();
$pdo->prepare('INSERT INTO admin_users(email,password_hash,created_at,updated_at) VALUES(? ,"x",?,?)')->execute(array('b'.$stamp.'@test.local',$now,$now));$a2=(int)$pdo->lastInsertId();
$f=new FeedbackService($pdo);$key='feedback_'.$stamp.'0001';$id=$f->create($uid,'bug','标题','环境、步骤、预期与实际',$key);ok($f->create($uid,'bug','标题','环境、步骤、预期与实际',$key)===$id,'submission retry idempotent');reject(function()use($f,$uid,$stamp){$f->create($uid,'suggestion','x','y','feedback_'.$stamp.'0002');$f->create($uid,'suggestion','x','y','feedback_'.$stamp.'0003');$f->create($uid,'suggestion','x','y','feedback_'.$stamp.'0004');$f->create($uid,'suggestion','x','y','feedback_'.$stamp.'0005');$f->create($uid,'suggestion','x','y','feedback_'.$stamp.'0006');},'submission rate limit','提交过于频繁');reject(function()use($f,$other,$id){$f->findMine($other,$id);},'ownership enforced','反馈不存在');$mine=$f->mine($uid);ok($mine['total']>=1,'owner pagination');$f->review($id,$a1,'rewarded','1.25','有效反馈奖励');$f->review($id,$a1,'rewarded','1.25','有效反馈奖励');ok((int)$pdo->query("SELECT COUNT(*) FROM wallet_transactions WHERE idempotency_key='feedback_reward:$id'")->fetchColumn()===1,'same review retry one ledger');reject(function()use($f,$id,$a2){$f->review($id,$a2,'rewarded','2.00','冲突金额');},'conflicting review rejected','参数冲突');ok((int)$pdo->query('SELECT balance_cents FROM users WHERE id='.$uid)->fetchColumn()===125,'reward balance');ok((int)$pdo->query("SELECT COUNT(*) FROM notifications WHERE user_id=$uid AND type='feedback_review'")->fetchColumn()===1,'single notification');ok((int)$pdo->query("SELECT COUNT(*) FROM admin_logs WHERE target_type='feedback' AND target_id=$id")->fetchColumn()===1,'single feedback audit');
$pdo->exec('UPDATE feedback_submissions SET created_at=DATE_SUB(NOW(),INTERVAL 2 HOUR) WHERE user_id='.$uid);
$id2=$f->create($uid,'suggestion','驳回','建议正文','feedback_'.$stamp.'0007');$f->review($id2,$a2,'rejected','0','暂不采纳');$f->review($id2,$a1,'rejected','0','暂不采纳');reject(function()use($f,$id2,$a1){$f->review($id2,$a1,'rejected','0','不同说明');},'rejection conflict rejected','参数冲突');ok(true,'rejection idempotency');
$old=$pdo->query("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='feedback_submissions' AND COLUMN_NAME='submission_key'")->fetchColumn();ok((int)$old===1,'submission key migrated');
reject(function()use($f,$uid,$key){$f->create($uid,'bug','不同内容','正文',$key);},'submission key content conflict','提交令牌已用于其他内容');
foreach(array('0','1e3','0.001','-1','10000000.00') as $amount)reject(function()use($f,$id2,$a1,$amount){$f->review($id2,$a1,'rewarded',$amount,'金额验证');},'invalid reward '.$amount,$amount==='0'?'奖励金额必须大于零':($amount==='10000000.00'?'金额超过钱包上限':'金额须为非负十进制数字'));
reject(function()use($f,$id2,$a1){$f->review($id2,$a1,'rewarded','1.00','');},'review note required','审核说明必填');
reject(function()use($f,$id2){$f->review($id2,PHP_INT_MAX,'rejected','0','非法管理员');},'unknown admin rejected','管理员身份无效');
ok(!$pdo->inTransaction(),'idempotent paths leave no open transaction');
$id3=$f->create($other,'bug','并发审核','正文','concurrent_'.$stamp.'001');
ok(parallel_reviews(array(array($id3,$a1,'2.00','并发奖励'),array($id3,$a2,'2.00','并发奖励')))===2,'two admins same feedback retry succeeds');
ok((int)$pdo->query("SELECT COUNT(*) FROM wallet_transactions WHERE idempotency_key='feedback_reward:$id3'")->fetchColumn()===1&&(int)$pdo->query('SELECT balance_cents FROM users WHERE id='.$other)->fetchColumn()===200,'concurrent reward credits once');
$id4=$f->create($other,'bug','容量竞争一','正文','capacity_'.$stamp.'001');$id5=$f->create($other,'suggestion','容量竞争二','正文','capacity_'.$stamp.'002');$pdo->exec('UPDATE users SET balance_cents='.(WalletService::MAX_BALANCE_CENTS-100).' WHERE id='.$other);
ok(parallel_reviews(array(array($id4,$a1,'1.00','容量奖励'),array($id5,$a2,'1.00','容量奖励')))===1,'capacity competition has one winner');
ok((int)$pdo->query('SELECT balance_cents FROM users WHERE id='.$other)->fetchColumn()===WalletService::MAX_BALANCE_CENTS,'exact wallet capacity never exceeded');
ok((int)$pdo->query('SELECT COUNT(*) FROM feedback_submissions WHERE id IN ('.$id4.','.$id5.') AND status="pending"')->fetchColumn()===1,'capacity failure leaves feedback pending');
class FeedbackFailurePDO extends PDO{public $fail='';public function prepare($query,$options=array()){if(($this->fail==='notification'&&strpos($query,'INSERT INTO notifications(')===0)||($this->fail==='audit'&&strpos($query,'INSERT INTO admin_logs(')===0))throw new RuntimeException('故障注入');return parent::prepare($query,$options);}}
$fp=new FeedbackFailurePDO($dsn,$user,$pass,array(PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false));
foreach(array('notification','audit') as $kind){$fid=$f->create($uid,'bug','回滚'.$kind,'正文','rollback_'.$stamp.$kind);$before=(int)$pdo->query('SELECT balance_cents FROM users WHERE id='.$uid)->fetchColumn();$fp->fail=$kind;reject(function()use($fp,$fid,$a1){(new FeedbackService($fp))->review($fid,$a1,'rewarded','3.00','回滚验证');},$kind.' failure propagates','故障注入');$row=$f->detail($fid);ok($row['status']==='pending'&&(int)$row['reward_cents']===0&&(int)$pdo->query('SELECT balance_cents FROM users WHERE id='.$uid)->fetchColumn()===$before,$kind.' rolls back balance and feedback');ok((int)$pdo->query("SELECT COUNT(*) FROM wallet_transactions WHERE idempotency_key='feedback_reward:$fid'")->fetchColumn()===0&&(int)$pdo->query("SELECT COUNT(*) FROM admin_logs WHERE target_type='feedback' AND target_id=$fid")->fetchColumn()===0,$kind.' rolls back ledger and review audit');}
echo 'TEST_DATABASE='.$pdo->query('SELECT DATABASE()')->fetchColumn().PHP_EOL;echo "FEEDBACK TESTS PASSED\n";
